//! The inventory taxonomy v1's types and tables: tool kinds, material kinds and the kits.
//!
//! Generated by tools/taxonomy_gen.py from the contract crew/contracts/mk_taxonomy.md
//! (ATLAS-api-harness), whose rows Claude chose and checked. Do not edit by hand: change the
//! contract and generate again. The lookups over these tables are in `taxonomy`.

/// How well a tool supplies a capability. Declared worst first, so Rough < Normal < Fine.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Grade {
    Rough,
    Normal,
    Fine,
}

/// How loud a tool is, for the apartment-friendly checks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Noise {
    Quiet,
    Moderate,
    Loud,
}

/// The forms of stock, in doc 04 section 4.3.2's order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Form {
    Board,
    Sheet,
    Rod,
    Tube,
    Fabric,
    Roll,
    Block,
    SheetPaper,
    Filament,
    Liquid,
    Granular,
}

/// How the maker has a tool (doc 04 section 4.3.1's access field).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Access {
    Owned,
    Shared,
    Makerspace,
    Rentable,
    Wishlist,
}

/// A kind of tool.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ToolKind {
    pub id: &'static str,
    pub name: &'static str,
    /// Phrases a maker might write, already in `taxonomy::words_of` form.
    pub words: &'static [&'static str],
    /// As written in the table: "cut.straight", "cut.straight:rough", "drill.hole:fine".
    pub supplies: &'static [&'static str],
    pub noise: Noise,
}

/// A kind of material.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MaterialKind {
    pub id: &'static str,
    pub name: &'static str,
    pub words: &'static [&'static str],
    /// The usual forms, the most usual first. Never empty.
    pub forms: &'static [Form],
    /// Must never be laser cut (doc 04: "laser-safe (PVC -> never)").
    pub laser_never: bool,
}

/// A fast-entry kit: pick it, then untick what you do not have.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Kit {
    pub id: &'static str,
    pub name: &'static str,
    pub access: Access,
    pub tools: &'static [&'static str],
}

